<template>
  <div>
    <el-button v-if="order.can_allocate" v-hasPermi="['order:order:allocate']" type="primary" size="small" @click="$emit('allocate')">{{ order.allocation_quantity ? '预览剩余分仓' : '预览分仓' }}</el-button>
    <el-alert v-if="order.allocation_error" :title="order.allocation_error" type="warning" :closable="false" show-icon />
    <el-descriptions :column="2" border class="summary"><el-descriptions-item label="分仓结果">{{ ({ NONE: '未分仓', PROCESSING: '分仓处理中', UNCERTAIN: '结果待确认，请重试核对', FAILED: '分仓失败', PART: '部分分仓', FULL: '全部分仓' })[order.allocation_status] || '未分仓' }}</el-descriptions-item><el-descriptions-item label="已分仓 / 有效需求">{{ order.allocation_quantity || 0 }} / {{ effectiveDemand }} 件</el-descriptions-item><el-descriptions-item label="待分仓余量">{{ order.status === 'VOIDED' ? 0 : Math.max(0, effectiveDemand - (order.allocation_quantity || 0)) }} 件</el-descriptions-item><el-descriptions-item label="最近分仓时间">{{ order.allocation_at || '—' }}</el-descriptions-item></el-descriptions>
    <p v-if="order.allocation_rule" class="muted">沿用首次分仓规则 v{{ order.allocation_rule.rule_revision || '—' }} · {{ order.allocation_rule.strategy === 'REGION_FIRST' ? '优先省份配置仓' : '优先整单' }} · 最多 {{ order.allocation_rule.max_virtual_warehouses || '不限' }} 个虚拟仓 / {{ order.allocation_rule.max_shipments || '不限' }} 张发货单 · 收货省份：{{ order.allocation_rule.receiver_province || '未识别，使用默认顺序' }} · 多虚拟仓：{{ order.allocation_rule.allow_multi ? '允许' : '不允许' }} · 部分发货：{{ order.allocation_rule.allow_partial ? '允许' : '不允许' }} · 同 SKU 跨虚拟仓：{{ order.allocation_rule.allow_split_sku ? '允许' : '不允许' }}</p>
    <el-alert v-if="(order.bundles||[]).some(b=>b.business_type==='LUCKY_BAG')" title="福袋按已固定的原袋商品和原批次分仓，每袋保持原发货仓" description="以下分仓与包裹数量为实际商品件数；原袋组成和完整发出袋数在商品明细查看。" type="info" :closable="false" show-icon/>
    <el-alert v-if="(order.bundles||[]).some(b=>b.business_type!=='LUCKY_BAG')" :title="order.allocation_rule&&order.allocation_rule.allow_bundle_partial_components?'套内组件允许分次发货，完整套数以组件全部出库为准':'套装按完整套数分仓；同一套的组件默认在同一虚拟仓'" :description="order.allocation_rule&&order.allocation_rule.allow_bundle_split?'本单允许套内组件跨虚拟仓。以下分仓和包裹数量均为实际组件件数。':'不同整套可以分仓；下方数量均为实际组件件数，销售套数在商品明细查看。'" type="info" :closable="false" show-icon/>
    <section v-if="warehouseGroups.length" class="allocation-fulfillment"><h3>各仓发货与包裹</h3><p class="muted">各虚拟仓独立发货；包裹关联在对应发货单下，由实际出库回传或运单登记确认，分仓时不预生成包裹。</p><article v-for="group in warehouseGroups" :key="group.key" class="allocation-warehouse"><div class="warehouse-title"><strong>{{ group.name }}</strong><span class="muted">实体仓 {{ group.realName }}（{{ group.realCode }}） · 货主 {{ group.owner }}</span><el-button v-hasPermi="['order:order:query']" type="text" :disabled="!group.shipments.length" @click="$refs.parcels.open(group.shipments, group.name + ' · 货主 ' + group.owner)">{{ group.packages ? '查看包裹（' + group.packages + ' 个）' : '包裹待回传 / 登记' }}</el-button></div><div class="warehouse-progress"><span>分配 <strong>{{ group.allocated }}</strong> 件</span><span>已出库 <strong>{{ group.shipped }}</strong> 件</span><span>剩余待出库 <strong>{{ group.remaining }}</strong> 件</span><span>{{ group.shipments.length }} 张发货单</span><span v-if="group.unpacked" class="warning">已出库待关联包裹 {{ group.unpacked }} 件</span></div><div class="warehouse-shipments"><el-button v-for="shipment in group.shipments" :key="shipment.id" v-hasPermi="['order:order:query']" type="text" @click="$refs.parcels.open([shipment], group.name + ' · ' + shipment.shipment_sn)">{{ shipment.shipment_sn }} · {{ shipment.package_count ? shipment.package_count + ' 个包裹' : '包裹待回传 / 登记' }}</el-button><span v-if="!group.shipments.length" class="muted">尚未生成发货单，尚无包裹</span></div></article></section>
    <el-table :data="order.warehouse_allocations || []" empty-text="尚无仓库分仓回执"><el-table-column label="虚拟仓 / 实体仓" min-width="230"><template slot-scope="s">{{ s.row.store_code }}<div class="muted">{{ s.row.real_store_name }}（{{ s.row.real_store_code }}） · 货主 {{ s.row.owner_code }}</div></template></el-table-column><el-table-column label="SKU / 平台子单" min-width="200"><template slot-scope="s">{{ s.row.sku_sn }}<div class="muted">{{ s.row.platform_oid }}</div></template></el-table-column><el-table-column label="批次 ID" prop="batch_id" width="100" /><el-table-column label="累计分仓 / 已出库 / 剩余占用" min-width="230"><template slot-scope="s">{{ s.row.quantity }} / {{ s.row.outbound_quantity || 0 }} / {{ order.status === 'VOIDED' ? 0 : Math.max(0, s.row.quantity - (s.row.outbound_quantity || 0)) }} 件</template></el-table-column><el-table-column label="占用来源" min-width="160"><template slot-scope="s">{{ s.row.source_type === 'LUCKY' ? '福袋原组件保障' : s.row.source_type === 'LOCK' ? '继承渠道锁库' : '公共库存转占用' }}<div class="muted">{{ order.status === 'VOIDED' ? '已释放' : Number(s.row.outbound_quantity) >= Number(s.row.quantity) ? '已出库' : s.row.outbound_quantity ? '部分出库，余量继续占用' : '已占用' }}</div></template></el-table-column></el-table>
    <shipment-packages-dialog ref="parcels" @changed="$emit('changed')" />
  </div>
</template>
<script>
import { warehouseFulfillmentGroups } from './packagePresentation'
import ShipmentPackagesDialog from './ShipmentPackagesDialog'
export default { components: { ShipmentPackagesDialog }, props: { order: { type: Object, required: true } }, computed: { effectiveDemand() { return Math.max(0, Number(this.order.demand_quantity || 0) - Number(this.order.cancelled_quantity || 0)) }, warehouseGroups() { return warehouseFulfillmentGroups(this.order) } } }
</script>
<style scoped>.summary{margin:16px 0}.muted{font-size:13px;color:#8490a2}.allocation-fulfillment h3{font-size:15px;margin:20px 0 10px;color:#27374c}.allocation-warehouse{border:1px solid #e4e9f0;border-radius:8px;padding:12px 16px;margin:10px 0}.warehouse-title,.warehouse-progress{display:flex;align-items:center;flex-wrap:wrap;gap:8px 20px}.warehouse-title strong{color:#36485f}.warehouse-title .el-button{margin-left:auto}.warehouse-progress{font-size:13px;color:#68778d;margin:10px 0}.warehouse-progress strong{color:#27374c}.warehouse-shipments{display:flex;flex-wrap:wrap;gap:4px 16px;overflow-wrap:anywhere}.warehouse-shipments .el-button{white-space:normal;text-align:left;margin:0;font-size:12px}.warning{color:#a46a10}</style>
